/** Decodifica la mascara a un Uint8Array de COLS*ROWS (1 = tierra, 0 = oceano), indexado fila por fila. */
function decodeLandMask() {
  const buf = Buffer.from(LAND_MASK_BASE64, 'base64');
  const mask = new Uint8Array(COLS * ROWS);
  for (let i = 0; i < COLS * ROWS; i++) {
    const byteIndex = i >> 3;
    const bitIndex = 7 - (i & 7);
    mask[i] = (buf[byteIndex] >> bitIndex) & 1;
  }
  return mask;
}

